-- Автогенерация из ai/knowledge_base.json (не править вручную)
INSERT INTO knowledge_base (code, question, answer, category, source, keywords) VALUES
  ('kb_projector_connect', 'Как подключить ноутбук к проектору?', '1) Убедитесь, что проектор подключён к питанию и включён; дождитесь окончания прогрева (индикатор перестанет мигать).
2) Соедините ноутбук и проектор кабелем HDMI (или VGA). Вставляйте разъём ровно, без усилия.
3) На проекторе выберите нужный вход (кнопка Source/Input: HDMI или VGA).
4) На ноутбуке с Windows нажмите Win+P и выберите «Повторяющийся» или «Только проектор». На macOS: Системные настройки → Мониторы.
5) Если изображения нет, проверьте, что кабель плотно вставлен с обеих сторон, и попробуйте другой порт или кабель.
Если не помогло или проектор не включается, оформите заявку.', 'equipment', 'Внутренняя инструкция УПК (демо)', ARRAY['проектор','подключить','ноутбук','hdmi','vga','экран','изображение']),
  ('kb_printer_basic', 'Что проверить, если принтер не печатает?', 'Безопасные базовые проверки:
1) Принтер включён, индикаторы не показывают ошибку.
2) В лотке есть бумага, нет явно застрявшего листа.
3) На компьютере выбран нужный принтер, очередь печати не завязла (отмените зависшие задания).
4) Кабель или сетевое подключение на месте; попробуйте выключить и снова включить принтер.
Не разбирайте принтер, не вытаскивайте застрявшую бумагу с усилием и не используйте инструменты. Если ошибка осталась, оформите заявку.', 'equipment', 'Внутренняя инструкция УПК (демо)', ARRAY['принтер','не печатает','печать','бумага','картридж','очередь']),
  ('kb_report_fault', 'Как сообщить о неисправности оборудования?', 'Опишите, что именно не работает, в каком помещении и с какого момента. Укажите, что уже пробовали сделать. По возможности приложите фотографию (общий вид и крупно место проблемы; инвентарный номер, если он виден). Затем отправьте заявку: вы получите номер и ссылку для отслеживания.', 'general', 'Внутренняя инструкция УПК (демо)', ARRAY['сообщить','неисправность','заявка','оформить','фото','сломалось']),
  ('kb_choose_category', 'Как выбрать категорию обращения?', 'Оборудование: проекторы, компьютеры, принтеры, интерактивные доски.
Мебель и имущество: столы, стулья, шкафы, жалюзи.
Электрика и освещение: свет, розетки, выключатели.
Сеть и интернет: Wi-Fi, сетевые розетки.
Здание: двери, окна, замки, потолок, стены.
Уборка и чистота: загрязнения, мусор.
Другое: если ничего не подходит. Сотрудник УПК при необходимости изменит категорию.', 'general', 'Внутренняя инструкция УПК (демо)', ARRAY['категория','выбрать','тип','обращение']),
  ('kb_property_damage', 'Что делать, если обнаружено повреждение имущества?', '1) Не пользуйтесь повреждённым предметом, если он может причинить травму (острые края, неустойчивая конструкция).
2) Сфотографируйте повреждение.
3) Не пытайтесь чинить самостоятельно.
4) Оформите заявку с указанием помещения и описанием. Если кто-то пострадал или есть острые осколки, сразу сообщите ответственному сотруднику.', 'furniture', 'Внутренняя инструкция УПК (демо)', ARRAY['повреждение','сломана','сломалась','мебель','стул','стол','дверь','окно','ручка']),
  ('kb_check_status', 'Где посмотреть статус заявки?', 'После отправки заявки система показывает её номер и персональную ссылку для отслеживания. Откройте эту ссылку, чтобы увидеть текущий статус, историю изменений и публичные комментарии сотрудников. Сохраните ссылку: по номеру одной заявки чужие заявки открыть нельзя.', 'general', 'Внутренняя инструкция УПК (демо)', ARRAY['статус','заявка','отслеживание','проверить','номер','ссылка']),
  ('kb_no_internet', 'Что делать, если нет интернета или не работает Wi-Fi?', '1) Отключитесь от Wi-Fi и подключитесь снова; перезагрузите своё устройство.
2) Если используется кабель, проверьте, что он плотно вставлен в ноутбук и в сетевую розетку.
3) Узнайте, есть ли интернет у других людей в помещении.
Не трогайте и не перезагружайте сетевое оборудование (роутеры, коммутаторы). Если проблема осталась, оформите заявку: укажите помещение, устройство и время начала проблемы.', 'network', 'Внутренняя инструкция УПК (демо)', ARRAY['интернет','wifi','wi-fi','сеть','не подключается','нет связи']),
  ('kb_light_not_working', 'Не работает свет в помещении, что делать?', 'Проверьте, включён ли выключатель, и работают ли остальные светильники. Не меняйте лампы, не открывайте светильники и не лазьте на стулья или столы. Если свет не включается, мигает или есть запах гари, оформите заявку (при запахе гари, дыме или искрении не приближайтесь и сразу сообщите ответственному сотруднику).', 'electricity', 'Внутренняя инструкция УПК (демо)', ARRAY['свет','освещение','лампа','не горит','выключатель']),
  ('kb_cleanliness', 'Как сообщить о загрязнении или беспорядке?', 'Оформите заявку в категории «Уборка и чистота»: укажите помещение и что именно загрязнено; фото ускорит обработку. Если пролито неизвестное вещество или на полу осколки, не трогайте их и сообщите ответственному сотруднику.', 'cleaning', 'Внутренняя инструкция УПК (демо)', ARRAY['грязно','уборка','мусор','загрязнение','пролито','чистота']),
  ('kb_timing', 'Когда решат мою проблему или починят оборудование?', 'Помощник не знает сроков ремонта. Сроки определяет сотрудник УПК после рассмотрения заявки. Актуальный статус и комментарии смотрите на странице отслеживания; если заявки ещё нет, оформите её.', 'general', 'Внутренняя инструкция УПК (демо)', ARRAY['когда','срок','починят','исправят','сколько ждать']),
  ('kb_access_secrets', 'Можно ли узнать пароль, доступ или служебные данные?', 'Пароли, коды доступа и служебные данные через помощника не выдаются. Для получения доступа обратитесь к ответственному сотруднику колледжа по официальной процедуре.', 'general', 'Внутренняя инструкция УПК (демо)', ARRAY['пароль','доступ','логин','служебный','код','wifi сотрудников'])
ON CONFLICT (code) DO UPDATE SET question=EXCLUDED.question, answer=EXCLUDED.answer, category=EXCLUDED.category, source=EXCLUDED.source, keywords=EXCLUDED.keywords, updated_at=now();
